void FAlsRigUnit_ApplyFootOffsetLocation::Initialize()
{
	bInitialized = false;
}

FAlsRigUnit_ApplyFootOffsetLocation_Execute()
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_RIGUNIT()

	const auto* Hierarchy{ExecuteContext.Hierarchy};

	if (!IsValid(Hierarchy) ||
	    !CachedPelvisItem.UpdateCache(PelvisItem, Hierarchy) ||
	    !CachedThighItem.UpdateCache(ThighItem, Hierarchy))
	{
		return;
	}

	const auto PelvisLocationZ{UE_REAL_TO_FLOAT(Hierarchy->GetGlobalTransform(CachedPelvisItem).GetLocation().Z)};
	const auto ThighLocation{Hierarchy->GetGlobalTransform(CachedThighItem).GetLocation()};

	const auto MaxFootLocationZ{PelvisLocationZ - MinPelvisToFootDistanceZ};
	const auto MaxFootOffsetLocationZ{MaxFootLocationZ - UE_REAL_TO_FLOAT(FootTargetLocation.Z)};

	// Limit how high the foot offset can raise the foot relative to the pelvis.
	auto TargetOffsetLocationZ{FMath::Min(FootOffsetLocationZ, MaxFootOffsetLocationZ)};

	// Do not allow the foot offset to be lower than the pelvis offset to prevent leg stretching.
	TargetOffsetLocationZ = FMath::Max(TargetOffsetLocationZ, PelvisOffset);

	if (!bInitialized)
	{
		bInitialized = true;

		OffsetSpringState.Reset();
		OffsetLocationZ = TargetOffsetLocationZ;
	}
	else
	{
		OffsetLocationZ = UAlsMath::SpringDamperFloat(OffsetSpringState, OffsetLocationZ, TargetOffsetLocationZ,
		                                              UE_REAL_TO_FLOAT(ExecuteContext.GetDeltaTime()), OffsetInterpolationFrequency,
		                                              OffsetInterpolationDampingRatio, OffsetInterpolationTargetVelocityAmount);
	}

	FootLocation.X = FootTargetLocation.X;
	FootLocation.Y = FootTargetLocation.Y;
	FootLocation.Z = FootTargetLocation.Z + OffsetLocationZ;

	// Prevent the leg from being fully straightened. We do this after offset interpolation, otherwise the effect will not be noticeable.

	const auto LegVector{FootLocation - ThighLocation};
	const auto ClampedLegVector{LegVector.GetClampedToMaxSize(LegLength * MaxLegStretchRatio)};

	FootLocation = ThighLocation + ClampedLegVector;
}

public:
	UPROPERTY(Meta = (Input, ExpandByDefault))
	FRigElementKey PelvisItem;

	UPROPERTY(Meta = (Input, ExpandByDefault))
	FRigElementKey ThighItem;

	UPROPERTY(Transient, Meta = (Input))
	FVector FootTargetLocation{ForceInit};

	UPROPERTY(Transient, Meta = (Input))
	float FootOffsetLocationZ{0.0f};

	UPROPERTY(Transient, Meta = (Input))
	float PelvisOffset{0.0f};

	UPROPERTY(Meta = (Input, ClampMin = 0, ForceUnits = "cm"))
	float LegLength{0.0f};

	/// Limits how high the foot can be raised relative to the pelvis.
	UPROPERTY(Meta = (Input, ClampMin = 0, ForceUnits = "cm"))
	float MinPelvisToFootDistanceZ{50.0f};

	/// Prevents legs from being fully straightened.
	UPROPERTY(Meta = (Input, ClampMin = 0.01, ForceUnits = "x"))
	float MaxLegStretchRatio{0.99f};

	/// Determines how hard the spring pulls towards the target. This value represents
	/// the frequency at which the spring oscillates when there is no damping.
	UPROPERTY(Meta = (Input, ClampMin = 0, ForceUnits = "hz"))
	float OffsetInterpolationFrequency{12.0};

	/// If less than 1, the spring will oscillate before settling on the target.
	/// If equal to 1, the spring will reach the target without overshooting.
	/// If greater than 1, the spring will take longer to reach the target.
	UPROPERTY(Meta = (Input, ClampMin = 0))
	float OffsetInterpolationDampingRatio{2.0f};

	/// Amount of velocity passed to the spring. A value of 1 results in a more responsive output. However, if the input
	/// is noisy or has step changes, these discontinuities will be more noticeable than they would be with a lower value.
	UPROPERTY(Meta = (Input, ClampMin = 0, ClampMax = 1))
	float OffsetInterpolationTargetVelocityAmount{0.0f};

	UPROPERTY(Transient)
	bool bInitialized{false};

	UPROPERTY(Transient)
	FCachedRigElement CachedPelvisItem;

	UPROPERTY(Transient)
	FCachedRigElement CachedThighItem;

	UPROPERTY(Transient)
	FAlsSpringFloatState OffsetSpringState;

	UPROPERTY(Transient)
	float OffsetLocationZ{0.0f};

	UPROPERTY(Transient, Meta = (Output))
	FVector FootLocation{ForceInit};

public:
	virtual void Initialize() override;

	RIGVM_METHOD()
	// ReSharper disable once CppFunctionIsNotImplemented
	virtual void Execute() override;
};

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::SizeSquared() const
{
    return X*X + Y*Y + Z*Z;
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::SquaredLength() const

template<typename T>
inline TVector<T> TVector<T>::GetClampedToMaxSize(T MaxSize) const
{
    if (MaxSize < UE_KINDA_SMALL_NUMBER)
    {
        return ZeroVector;
    }

    const T VSq = SizeSquared();
    if (VSq > FMath::Square(MaxSize))
    {
        const T Scale = MaxSize * FMath::InvSqrt(VSq);
        return TVector<T>(X*Scale, Y*Scale, Z*Scale);
    }
    else
    {
        return *this;
    }	
}

